type chipInfo struct {
	key   string
	label string
	count int
}

func getChips(items []Item) []chipInfo {
	counts := map[string]int{"all": len(items)}
	for _, it := range items {
		counts[it.Category]++
	}

	order := []struct {
		key   string
		label string
	}{
		{"all", "All"},
		{"push", "Pushes"},
		{"star", "Stars"},
		{"pull", "Pulls"},
		{"issue", "Issues"},
		{"release", "Releases"},
		{"comment", "Comments"},
		{"repo", "Repos"},
		{"other", "Other"},
	}

	var res []chipInfo
	for _, o := range order {
		if c, ok := counts[o.key]; ok && (o.key == "all" || c > 0) {
			res = append(res, chipInfo{key: o.key, label: o.label, count: c})
		}
	}
	return res
}

